	_ interface{ Unwrap() error } = &Error{}
)

func TestZZTmpUnwrap(t *testing.T) {
	sentinel := tmpSentinel{}

	// pointer form
	perr := fmt.Errorf("wrapped: %w", &Error{Err: sentinel, Type: ErrorTypeAny})
	if !errors.Is(perr, sentinel) {
		t.Errorf("pointer form: errors.Is failed")
	}
	var pt tmpSentinel
	if !errors.As(perr, &pt) {
		t.Errorf("pointer form: errors.As failed")
	}
	var pge *Error
	if !errors.As(perr, &pge) {
		t.Errorf("pointer form: errors.As(*Error) failed")
	}

	// value form
	verr := fmt.Errorf("wrapped: %w", Error{Err: sentinel, Type: ErrorTypeAny})
	if !errors.Is(verr, sentinel) {
		t.Errorf("value form: errors.Is failed")
	}
	var vt tmpSentinel
	if !errors.As(verr, &vt) {
		t.Errorf("value form: errors.As failed")
	}

	// direct value form
	if !errors.Is(Error{Err: sentinel}, sentinel) {
		t.Errorf("direct value form: errors.Is failed")
	}
	if got := errors.Unwrap(Error{Err: sentinel}); got != sentinel {
		t.Errorf("direct value form: errors.Unwrap = %v, want sentinel", got)
	}
	if got := errors.Unwrap(&Error{Err: sentinel}); got != sentinel {
